+static uint32_t
+someip_payload_peek_wtlv_length(tvbuff_t *tvb, int offset)
+{
+    if (offset < 0 || tvb_captured_length_remaining(tvb, offset) < 2)
+    {
+        return 0;
+    }
+
+    uint16_t raw_tag = tvb_get_ntohs(tvb, offset);
+    unsigned wiretype = (unsigned)((raw_tag & SOMEIP_WTLV_MASK_WIRE_TYPE) >> 12);
+
+    switch (wiretype)
+    {
+    case 5:
+        return 8;
+    case 6:
+        return 16;
+    case 7:
+        return 32;
+    default:
+        return 0;
+    }
+}
+
+static int64_t
+someip_payload_read_length_value(tvbuff_t *tvb, int offset, uint32_t length_of_length)
+{
+    switch (length_of_length)
+    {
+    case 8:
+        return (int64_t)tvb_get_uint8(tvb, offset);
+    case 16:
+        return (int64_t)tvb_get_ntohs(tvb, offset);
+    case 32:
+        return (int64_t)tvb_get_ntohl(tvb, offset);
+    default:
+        return -1;
+    }
+}
