+static int
+dissect_someip_payload_uuid(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, int offset, uint32_t id, char *name, int *hf_id_ptr, int wtlv_offset)
+{
+    someip_parameter_uuid_t *config = NULL;
+
+    proto_item *ti = NULL;
+    proto_tree *subtree = NULL;
+
+    int offset_orig = offset;
+    uint32_t declared_length = 16;
+    uint32_t consumed_length_field = 0;
+
+    config = get_uuid_config(id);
+    if (config == NULL)
+    {
+        return 0;
+    }
+
+    const char *display_name = name ? name : (config->name ? config->name : "uuid");
+    const char *config_name = config->name ? config->name : display_name;
+
+    uint32_t length_of_length = someip_payload_peek_wtlv_length(tvb, wtlv_offset);
+    if (length_of_length == 0)
+    {
+        length_of_length = config->length_of_length;
+    }
+
+    int length_field_offset = offset;
+    if (length_of_length != 0)
+    {
+        if (tvb_captured_length_remaining(tvb, offset) < (int)(length_of_length / 8))
+        {
+            expert_someip_payload_malformed(tree, pinfo, tvb, offset, 0);
+            return 0;
+        }
+
+        int64_t tmp = someip_payload_read_length_value(tvb, offset, length_of_length);
+        consumed_length_field = length_of_length / 8;
+        if (tmp < 0)
+        {
+            return consumed_length_field;
+        }
+        declared_length = (uint32_t)tmp;
+        offset += consumed_length_field;
+    }
+
+    int hf_value = hf_payload_uuid;
+    if (hf_id_ptr != NULL)
+    {
+        hf_value = *hf_id_ptr;
+    }
+    else if (config->hf_id != NULL)
+    {
+        hf_value = *(config->hf_id);
+    }
+
+    ti = proto_tree_add_item(tree, hf_value, tvb, offset, declared_length, ENC_BIG_ENDIAN);
+    subtree = proto_item_add_subtree(ti, ett_someip_uuid);
+    dissect_someip_payload_add_wtlv_if_needed(tvb, pinfo, wtlv_offset, ti, subtree);
+
+    if (length_of_length != 0)
+    {
+        dissect_someip_payload_length_field(tvb, pinfo, subtree, length_field_offset, length_of_length);
+    }
+
+    if (declared_length != 16)
+    {
+        proto_tree_add_expert_format(subtree, pinfo, &ei_someip_payload_uuid_length, tvb, offset - (int)consumed_length_field, consumed_length_field,
+                                     "UUID payload length must be 16 bytes but is %u", declared_length);
+        col_append_str(pinfo->cinfo, COL_INFO, " [SOME/IP Payload: UUID length != 16]");
+
+        int available_bytes = tvb_captured_length_remaining(tvb, offset);
+        int bytes_consumed = (int)declared_length;
+        if (available_bytes < bytes_consumed)
+        {
+            expert_someip_payload_truncated(subtree, pinfo, tvb, offset, available_bytes);
+            bytes_consumed = available_bytes;
+        }
+
+        proto_item_set_end(ti, tvb, offset + bytes_consumed);
+        offset += bytes_consumed;
+        return offset - offset_orig;
+    }
+
+    int remaining_bytes = tvb_captured_length_remaining(tvb, offset);
+    if ((int)declared_length > remaining_bytes)
+    {
+        expert_someip_payload_truncated(subtree, pinfo, tvb, offset, remaining_bytes);
+        proto_item_set_end(ti, tvb, offset + remaining_bytes);
+        return offset - offset_orig + remaining_bytes;
+    }
+
+    e_guid_t guid_value;
+    tvb_get_guid(tvb, offset, &guid_value, ENC_BIG_ENDIAN);
+
+    const char *guid_str = guid_to_str(pinfo->pool, &guid_value);
+
+    if (guid_str != NULL)
+    {
+        proto_item_set_text(ti, "uuid %s [%s]: %s", display_name, config_name, guid_str);
+    }
+    else
+    {
+        proto_item_set_text(ti, "uuid %s [%s]", display_name, config_name);
+    }
+
+    if (someip_deserializer_debugging_activated)
+    {
+        proto_item_append_text(ti, "  [Debug: UUID ID 0x%04x]", id);
+    }
+
+    offset += declared_length;
+    proto_item_set_end(ti, tvb, offset);
+
+    return offset - offset_orig;
+}
